class Cites:
    """assign reference numbers in order of first citation"""

    def __init__(self):
        self.order = []

    def __call__(self, *keys):
        nums = []
        for k in keys:
            if k not in REFS:
                raise KeyError(k)
            if k not in self.order:
                self.order.append(k)
            nums.append(self.order.index(k) + 1)
        return "[" + ",".join(str(n) for n in sorted(nums)) + "]"

    def listing(self):
        return [(i + 1, REFS[k]) for i, k in enumerate(self.order)]
